const clearRelicTooltipTimers = () => {
  if (relicTooltipLongPressTimer) {
    clearTimeout(relicTooltipLongPressTimer);
    relicTooltipLongPressTimer = null;
  }
  if (relicTooltipAutoHideTimer) {
