  const viewport = mapViewportRef.value;
  if (!viewport) return { x: clientX, y: clientY };
  const rect = viewport.getBoundingClientRect();
  return {
    x: clientX - rect.left - viewport.clientLeft,
    y: clientY - rect.top - viewport.clientTop,
  };
};
